/**
 * Streak freeze (SRS v2 phase E): the server is the judge of the streak too.
 *
 * The streak is worked out on every device (`advanceStreak` in core), and
 * the server works it out the same way from the answers it receives. With
 * freeze on, two devices can each spend a freeze offline, so this device
 * adopts the server's streak whenever the server tells it, with nothing of
 * its own still queued: after a push of answers (`POST /reviews` answers
 * with the streak), and from the switch itself.
 *
 * An account that never turned freeze on is left exactly as before: the
 * streak is adopted only when freeze is, or was, on.
 */
import type { Streak } from '@lexpad/core';
import type { ApiStreak } from '@/api/types.js';
import { db, getMeta, setMeta, type LexpadDb } from '@/db/schema.js';

/** The server's streak in the engine's shape, keeping what the server does not send. */
export function streakFromApi(api: ApiStreak, local: Streak): Streak {
  return {
    current: api.current,
    longest: api.longest,
    ...(api.lastActiveDay === undefined
      ? local.lastActiveDay === undefined
        ? {}
        : { lastActiveDay: local.lastActiveDay }
      : { lastActiveDay: api.lastActiveDay }),
    freezeOn: api.freezeOn === true,
    freezes: api.freezes ?? 0,
    frozenDays: api.frozenDays ?? [],
    ...(local.lastFreezeEarnedDay === undefined ? {} : { lastFreezeEarnedDay: local.lastFreezeEarnedDay }),
  };
}

/**
 * Takes the server's streak after a push, unless an answer is still queued
 * (it would be counted twice: once in the server's streak, once more when
 * this device's copy of it is advanced again).
 */
export async function adoptServerStreak(
  api: ApiStreak | undefined,
  database: LexpadDb = db,
): Promise<boolean> {
  if (api?.freezeOn === undefined) return false;
  return database.transaction('rw', [database.meta, database.outbox], async () => {
    const local = await getMeta('streak', database);
    if (api.freezeOn !== true && local.freezeOn !== true) return false;
    const queued = await database.outbox.where('entity').equals('review').count();
    if (queued > 0) return false;
    await setMeta('streak', streakFromApi(api, local), database);
    return true;
  });
}

/** Takes the server's answer to the switch: it is the streak as it stands. */
export async function applyFreezeAnswer(api: ApiStreak, database: LexpadDb = db): Promise<void> {
  await database.transaction('rw', database.meta, async () => {
    const local = await getMeta('streak', database);
    // The switch answers the streak the server holds; answers this device
    // has not sent yet are still in its own count, so the count stays local
    // and only the freeze state is taken.
    await setMeta(
      'streak',
      {
        ...local,
        freezeOn: api.freezeOn === true,
        freezes: api.freezes ?? local.freezes ?? 0,
        frozenDays: api.frozenDays ?? local.frozenDays ?? [],
      },
      database,
    );
  });
}
