/**
 * Keeps the host's reminders in step with the synced setting and with what
 * the learner has done. Runs at boot, after a change in Settings, after every
 * pull and when a session ends, so the plan is rebuilt whenever the app is
 * used: a time chosen on another device takes effect here without a restart,
 * a finished session cancels tonight's streak nudge, and opening the app
 * starts the absence count again from today.
 *
 * Runs are serialised. Boot and the first pull land within the same second,
 * and a host can hold only one permission prompt at a time: the second
 * request would be answered "denied" while the first dialog was still open.
 */
import { activeToday, dayIndex, effectiveStreak, isDue, type Streak } from '@lexpad/core';
import { getActiveNotebook, listWords, loadSettings, loadStreak } from '@/db/repo.js';
import { getMeta } from '@/db/schema.js';
import { t } from '@/i18n/index.js';
import { platform } from '@/lib/platform/index.js';
import type { Notice, ReminderStatus, ReminderText } from '@/lib/platform/types.js';
import { localTimeZone } from '@/lib/format.js';

let queue: Promise<unknown> = Promise.resolve();

export function syncReminder(now: Date = new Date()): Promise<ReminderStatus> {
  const run = async (): Promise<ReminderStatus> => {
    const settings = await loadSettings();
    const time = settings?.reminderTime ?? null;
    if (time === null) return platform.reminders.schedule(null);
    const notebook = await getActiveNotebook();
    const words = notebook ? await listWords(notebook.id) : [];
    const dueOn = (day: number): number =>
      words.filter(
        (word) => word.progress !== undefined && !word.progress.retired && isDue(word.progress, day),
      ).length;
    const dueWordOn = (day: number): string | undefined => {
      const due = words.filter(
        (word) => word.progress !== undefined && !word.progress.retired && isDue(word.progress, day),
      );
      return due.length === 1 ? due[0]?.headword : undefined;
    };
    const unstarted = words.filter((word) => word.progress === undefined).length;
    // The server sends come-back to an install it can reach; see pushReceives.
    const serverPush = await getMeta('pushReceives');
    const timeZone = localTimeZone();
    const createdAt = (await getMeta('user'))?.createdAt;
    const created = createdAt === undefined ? Number.NaN : Date.parse(createdAt);
    return platform.reminders.schedule(
      planReminders({
        time,
        now,
        timeZone,
        streak: await loadStreak(),
        dueOn,
        serverPush,
        dueWordOn,
        unstarted,
        ...(Number.isNaN(created) ? {} : { firstDay: dayIndex(new Date(created), timeZone) }),
      }),
    );
  };
  const turn = queue.then(run, run);
  queue = turn.catch(() => undefined);
  return turn;
}

/**
 * The days of an absence that hear the ordinary daily reminder: today and
 * the two after it (offsets 0–2). From the third day somebody is away, and a
 * reminder that rang every day has become noise; the plan is rebuilt every
 * time the app is opened, so a learner who uses it daily hears it daily.
 * (Lifecycle plan, 2026-10-09, §2g.)
 */
export const DAILY_DAYS = 3;

/**
 * Days without opening the app on which a phone the server cannot reach
 * speaks to somebody who has been away. Nothing rings in between (days 4–6
 * are quiet), and after a month the app goes quiet for good: somebody who
 * has not come back in thirty days has decided, and a notebook that keeps
 * asking is one that gets uninstalled. A phone the server reaches hears
 * days 3 and 14 from the server instead, and the plan leaves all four out.
 */
export const COMEBACK_DAYS = [3, 7, 14, 30] as const;

/** Tonight's streak nudge, when the daily reminder does not already fall in the evening. */
export const STREAK_NUDGE_AT = '21:30';

/** A daily reminder at or after this hour carries the streak nudge itself. */
const EVENING_FROM = 19;

/**
 * The shortest streak worth defending out loud. Two days is yesterday and
 * today; three is a habit starting (lifecycle plan, message S).
 */
export const STREAK_WORTH_SAVING = 3;

/** Id blocks within the host's reminder range (1–20). */
const DAILY_ID = 1; // 1–3: today and the two days after
const COMEBACK_ID = 4; // 4–7: the day 3, 7, 14 and 30 nudges
const STREAK_ID = 8;

/** The lines a quiet day rotates through, so the nudge does not wear out. */
const LINES = [
  'reminder.line1',
  'reminder.line2',
  'reminder.line3',
  'reminder.line4',
  'reminder.line5',
] as const;

export interface PlanInput {
  /** The daily reminder time, "HH:mm" in local time. */
  time: string;
  now: Date;
  timeZone: string;
  streak: Streak;
  /** How many words will be due on a local day index. */
  dueOn: (day: number) => number;
  /**
   * Whether the server can reach this install with a push (its last
   * registration carried a token; see `pushReceives`). The server then sends
   * the come-back nudges, so the plan carries none of its own. Absent means
   * false: a phone nobody else can reach keeps its own voice.
   */
  serverPush?: boolean;
  /**
   * The local day the account was made. Its next day (`FIRST_REVIEW_DAY`)
   * the daily reminder speaks of the first review (`firstReviewText`).
   */
  firstDay?: number;
  /** The one due word's headword on a day exactly one is due, else undefined. */
  dueWordOn?: (day: number) => string | undefined;
  /** Words in the notebook never practised yet. */
  unstarted?: number;
}

/**
 * The day after sign-up (growth audit 2026-10-26: 17% practise on it). Its
 * daily reminder, at the learner's own time and never a second one, says
 * what that day really holds for a new notebook: the words back for their
 * first review, or, with nothing due and nothing ever practised, the words
 * waiting for their first practice. A day with practice already is left as
 * it was (the plan is rebuilt when a session ends).
 */
export const FIRST_REVIEW_DAY = 1;

/**
 * The notifications for the days ahead, written fresh from local data.
 *
 * - The daily reminder today and on the next two days, at the chosen time,
 *   each saying what that day holds. A reminder that has already passed
 *   today is left out.
 * - On the third day of not opening the app, and on the seventh, fourteenth
 *   and thirtieth, a come-back nudge, unless the server sends those to this
 *   install. Nothing else from the fourth day on.
 * - A streak of three or more days that today has not yet kept gets an
 *   evening nudge. If today's reminder already falls in the evening it says
 *   it; if not, one more notification comes at half past nine. With a
 *   streak freeze ready to cover tonight it says the streak is safe rather
 *   than that it ends at midnight, because that would not be true.
 */
export function planReminders({
  time,
  now,
  timeZone,
  streak,
  dueOn,
  serverPush = false,
  firstDay,
  dueWordOn,
  unstarted = 0,
}: PlanInput): Notice[] {
  const [hours = 0, minutes = 0] = time.split(':').map(Number);
  const today = dayIndex(now, timeZone);
  const at = (offset: number, h = hours, m = minutes): Date =>
    new Date(now.getFullYear(), now.getMonth(), now.getDate() + offset, h, m, 0, 0);
  const title = t('reminder.title');
  const plan: Notice[] = [];

  const current = effectiveStreak(streak, today);
  const atRisk = current >= STREAK_WORTH_SAVING && !activeToday(streak, today);
  const streakText: ReminderText = { title, body: streakLine(streak, today, current) };

  for (let offset = 0; offset < DAILY_DAYS; offset += 1) {
    const when = at(offset);
    if (when.getTime() <= now.getTime()) continue;
    const day = today + offset;
    const firstReview =
      firstDay !== undefined && day - firstDay === FIRST_REVIEW_DAY && !activeToday(streak, day)
        ? firstReviewText(dueOn(day), dueWordOn?.(day), streak.lastActiveDay === undefined ? unstarted : 0)
        : undefined;
    const text =
      offset === 0 && atRisk && hours >= EVENING_FROM
        ? streakText
        : (firstReview ?? dailyText(day, dueOn(day)));
    plan.push({ id: DAILY_ID + offset, at: when, ...text });
  }

  if (!serverPush) {
    COMEBACK_DAYS.forEach((offset, index) => {
      const day = today + offset;
      plan.push({ id: COMEBACK_ID + index, at: at(offset), ...comebackText(day, dueOn(day)) });
    });
  }

  if (atRisk && hours < EVENING_FROM) {
    const [nudgeHours = 21, nudgeMinutes = 30] = STREAK_NUDGE_AT.split(':').map(Number);
    const when = at(0, nudgeHours, nudgeMinutes);
    if (when.getTime() > now.getTime()) plan.push({ id: STREAK_ID, at: when, ...streakText });
  }

  return plan;
}

/** A non-negative remainder, so a rotation works for any day index. */
function turn(day: number, length: number): number {
  return ((day % length) + length) % length;
}

/**
 * Whether a streak freeze will cover tonight if the learner does nothing:
 * the switch is on and one is left after the days already missed have
 * spent theirs (`effectiveStreak` counts the same way).
 */
export function freezeReadyTonight(streak: Streak, today: number): boolean {
  if (streak.freezeOn !== true || streak.lastActiveDay === undefined) return false;
  const missed = Math.max(0, today - streak.lastActiveDay - 1);
  return (streak.freezes ?? 0) - missed >= 1;
}

/** What tonight's streak nudge says: the freeze line when one is ready, else one of two. */
function streakLine(streak: Streak, today: number, count: number): string {
  if (freezeReadyTonight(streak, today)) return t('reminder.streakFreeze', { count });
  return turn(today, 2) === 0
    ? t('reminder.streak', { count })
    : t('reminder.streakNext', { count, next: count + 1 });
}

/** What an ordinary day's reminder says: the count when there is one, else the day's line. */
function dailyText(day: number, due: number): ReminderText {
  const title = t('reminder.title');
  if (due === 1) return { title, body: t('reminder.dueOne') };
  if (due > 1) return { title, body: t('reminder.due', { count: due }) };
  return { title, body: t(LINES[turn(day, LINES.length)] ?? 'reminder.line1') };
}

/**
 * The day after sign-up, in a new learner's words (uiux 2026-10-26-activation
 * §a): the words back for their first review by name or number, else the words
 * saved and never practised, else nothing special (undefined).
 */
function firstReviewText(due: number, word: string | undefined, unstarted: number): ReminderText | undefined {
  if (due === 1 && word !== undefined) {
    return { title: t('reminder.firstReviewTitle'), body: t('reminder.firstReviewOne', { word }) };
  }
  // One due word whose name the plan could not take (the two reads differ on
  // retired words): still the singular, never "1 of your words are".
  if (due === 1) return { title: t('reminder.firstReviewTitle'), body: t('reminder.firstReviewOneUnnamed') };
  if (due > 0)
    return { title: t('reminder.firstReviewTitle'), body: t('reminder.firstReview', { count: due }) };
  if (unstarted === 1)
    return { title: t('reminder.firstPracticeTitle'), body: t('reminder.firstPracticeOne') };
  if (unstarted > 1) {
    return {
      title: t('reminder.firstPracticeTitle'),
      body: t('reminder.firstPractice', { count: unstarted }),
    };
  }
  return undefined;
}

/** What a reminder says to somebody who has been away, in one of two wordings by day. */
function comebackText(day: number, due: number): ReminderText {
  const title = t('reminder.title');
  const second = turn(day, 2) === 1;
  if (due === 1) return { title, body: t('reminder.comebackOne') };
  if (due > 1) return { title, body: t(second ? 'reminder.comeback2' : 'reminder.comeback', { count: due }) };
  return { title, body: t(second ? 'reminder.comebackQuiet2' : 'reminder.comebackQuiet') };
}
