/**
 * The server's rules for a word, mirrored so nothing this device queues can
 * be refused for them (code review, 26 Oct 2026). A word the server refuses
 * never leaves the device, so every rule of `lexpad_back`
 * `internal/domain/word/word.go` (`Normalize`, then `Validate`) is copied
 * here. Keep the two in step; the constants carry the Go names.
 *
 * Normalize: headword, category, level and each meaning and gloss are
 * trimmed; an empty category is "general"; an empty source is "manual"; the
 * level is upper-cased.
 *
 * Validate:
 *  1. headword 1–200 characters (`MaxHeadwordLen`);
 *  2. level empty or one of A1, A2, B1, B2, C1, C2;
 *  3. source one of manual, ai, import, shared, assistant;
 *  4. category at most 60 characters (`MaxCategoryLen`);
 *  5. pos and pronunciation at most 200 characters (`MaxShortTextLen`);
 *  6. spellingNote, originalMeaning, correction, usageNote, relatedNote at
 *     most 2000 characters (`MaxNoteLen`);
 *  7. at most 20 meanings (`MaxMeanings`);
 *  8. every meaning not empty; meaning and gloss at most 2000 characters;
 *  9. at most 10 examples a meaning (`MaxExamplesPerMean`);
 * 10. every example sentence not blank; sentence and translation at most
 *     2000 characters;
 * 11. expressions, collocations, related words and related ids at most 50
 *     each (`MaxListItems`);
 * 12. every phrase's text and translation, and every collocation, at most
 *     2000 characters;
 * 13. a word is not related to itself.
 *
 * The 2000-character caps on meanings, glosses, examples, phrases and
 * collocations (8, 10, 12) are the server's own since `3de43c3` (10 Oct 2026,
 * "cap every free-text field of a word on the server"): a longer one is
 * refused with the whole word, so it is clipped here and the clip counted
 * (and, on a push, reported).
 *
 * `wordProblems` says what the server would refuse; `fitToServer` makes a
 * word it takes, moving what does not fit into the usage note rather than
 * dropping it, and counts what even the note cannot hold.
 */

export const MAX_HEADWORD_LEN = 200;
export const MAX_SHORT_TEXT_LEN = 200;
export const MAX_NOTE_LEN = 2000;
export const MAX_CATEGORY_LEN = 60;
export const MAX_MEANINGS = 20;
export const MAX_LIST_ITEMS = 50;
/** A learner's note on their progress (`maxMemoRunes` in handlers/words.go, OpMemo in app/learn). */
export const MAX_MEMO_LEN = 2000;
export const MAX_EXAMPLES_PER_MEANING = 10;
const DEFAULT_CATEGORY = 'general';
const LEVELS = new Set(['A1', 'A2', 'B1', 'B2', 'C1', 'C2']);
const SOURCES = new Set(['manual', 'ai', 'import', 'shared', 'assistant']);
const NOTES = ['spellingNote', 'originalMeaning', 'correction', 'usageNote', 'relatedNote'] as const;

interface Example {
  sentence?: string | undefined;
  translation?: string | undefined;
}
interface Sense {
  meaning?: string | undefined;
  gloss?: string | undefined;
  examples?: Example[] | undefined;
}
interface Phrase {
  text?: string | undefined;
  translation?: string | undefined;
}

/** A word as the rules read it: the local shape and the push payload share these names. */
export interface WordShape {
  id?: string | undefined;
  headword?: string | undefined;
  category?: string | undefined;
  source?: string | undefined;
  level?: string | undefined;
  pos?: string | undefined;
  pronunciation?: string | undefined;
  spellingNote?: string | undefined;
  originalMeaning?: string | undefined;
  correction?: string | undefined;
  usageNote?: string | undefined;
  relatedNote?: string | undefined;
  meanings?: Sense[] | undefined;
  expressions?: Phrase[] | undefined;
  collocations?: string[] | undefined;
  relatedWords?: Phrase[] | undefined;
  relatedWordIds?: string[] | undefined;
}

const length = (value: string | undefined): number => [...(value ?? '')].length;
const clip = (value: string, max: number): string => [...value].slice(0, max).join('');

/** What the server would refuse in this word, in its own words; empty when it takes it. */
export function wordProblems(word: WordShape): string[] {
  const problems: string[] = [];
  const headword = (word.headword ?? '').trim();
  if (length(headword) === 0 || length(headword) > MAX_HEADWORD_LEN)
    problems.push('headword must be 1–200 characters');
  const level = (word.level ?? '').trim().toUpperCase();
  if (level !== '' && !LEVELS.has(level)) problems.push('level must be one of A1, A2, B1, B2, C1, C2');
  if (!SOURCES.has(word.source === undefined || word.source === '' ? 'manual' : word.source))
    problems.push('unknown source');
  if (length((word.category ?? '').trim()) > MAX_CATEGORY_LEN) problems.push('category too long');
  for (const name of ['pos', 'pronunciation'] as const)
    if (length(word[name]) > MAX_SHORT_TEXT_LEN) problems.push(`${name} too long`);
  for (const name of NOTES) if (length(word[name]) > MAX_NOTE_LEN) problems.push(`${name} too long`);
  const meanings = word.meanings ?? [];
  if (meanings.length > MAX_MEANINGS) problems.push('too many meanings');
  meanings.forEach((sense, i) => {
    const meaning = (sense.meaning ?? '').trim();
    if (meaning === '') problems.push(`meanings[${String(i)}].meaning is required`);
    if (length(meaning) > MAX_NOTE_LEN || length((sense.gloss ?? '').trim()) > MAX_NOTE_LEN)
      problems.push(`meanings[${String(i)}] is too long`);
    const examples = sense.examples ?? [];
    if (examples.length > MAX_EXAMPLES_PER_MEANING)
      problems.push(`meanings[${String(i)}] has too many examples`);
    examples.forEach((example, j) => {
      if ((example.sentence ?? '').trim() === '')
        problems.push(`meanings[${String(i)}].examples[${String(j)}].sentence is required`);
      if (length(example.sentence) > MAX_NOTE_LEN || length(example.translation) > MAX_NOTE_LEN)
        problems.push(`meanings[${String(i)}].examples[${String(j)}] is too long`);
    });
  });
  const lists = [word.expressions, word.collocations, word.relatedWords, word.relatedWordIds];
  if (lists.some((list) => (list ?? []).length > MAX_LIST_ITEMS)) problems.push('too many list items');
  for (const list of [word.expressions, word.relatedWords])
    for (const phrase of list ?? [])
      if (length(phrase.text) > MAX_NOTE_LEN || length(phrase.translation) > MAX_NOTE_LEN)
        problems.push('a phrase is too long');
  for (const collocation of word.collocations ?? [])
    if (length(collocation) > MAX_NOTE_LEN) problems.push('a collocation is too long');
  if (word.id !== undefined && (word.relatedWordIds ?? []).includes(word.id))
    problems.push('a word cannot be related to itself');
  return problems;
}

/** The old name, for the senses only. */
export function meaningProblems(word: WordShape): string[] {
  return wordProblems({ headword: 'x', meanings: word.meanings }).filter((problem) =>
    problem.startsWith('meanings'),
  );
}

const quoted = (sentence: string): string => `“${sentence.trim()}”`;

/**
 * The word as the server takes it. What does not fit a field moves to the
 * usage note, one line each: a meaning past the twentieth, an example past
 * the tenth of its meaning, an example whose meaning is blank, a list item
 * past the fiftieth, a part of speech or a reading past 200 characters.
 * The note keeps whole lines up to 2000 characters; `cut` counts the lines
 * (and the clipped texts) that did not fit even there, for the screen to say.
 * An unknown level is dropped, an unknown source becomes "import" and an
 * over-long category "general". A headword out of bounds is left for the
 * caller, which skips such a word.
 */
export function fitToServer<T extends WordShape>(word: T): { word: T; cut: number } {
  const overflow: string[] = [];
  let cut = 0;
  const fit = (value: string): string => {
    if (length(value) <= MAX_NOTE_LEN) return value;
    cut += 1;
    return clip(value, MAX_NOTE_LEN);
  };
  const next: T = { ...word };

  if (word.meanings !== undefined) {
    const senses: Sense[] = [];
    for (const sense of word.meanings) {
      const sentences = (sense.examples ?? []).filter((example) => (example.sentence ?? '').trim() !== '');
      const meaning = (sense.meaning ?? '').trim();
      if (meaning === '') {
        overflow.push(...sentences.map((example) => quoted(example.sentence ?? '')));
        continue;
      }
      if (senses.length >= MAX_MEANINGS) {
        const examples = sentences.map((example) => quoted(example.sentence ?? ''));
        overflow.push([meaning, ...examples].join(' '));
        continue;
      }
      const kept = sentences.slice(0, MAX_EXAMPLES_PER_MEANING).map((example) => ({
        ...example,
        sentence: fit(example.sentence ?? ''),
        ...(example.translation === undefined ? {} : { translation: fit(example.translation) }),
      }));
      overflow.push(
        ...sentences.slice(MAX_EXAMPLES_PER_MEANING).map((example) => quoted(example.sentence ?? '')),
      );
      senses.push({
        ...sense,
        meaning: fit(meaning),
        ...(sense.gloss === undefined ? {} : { gloss: fit(sense.gloss) }),
        examples: kept,
      });
    }
    next.meanings = senses;
  }

  const phrases = (list: Phrase[] | undefined): Phrase[] | undefined => {
    if (list === undefined) return undefined;
    overflow.push(
      ...list
        .slice(MAX_LIST_ITEMS)
        .map((phrase) =>
          phrase.translation === undefined
            ? (phrase.text ?? '')
            : `${phrase.text ?? ''} (${phrase.translation})`,
        ),
    );
    return list.slice(0, MAX_LIST_ITEMS).map((phrase) => ({
      ...phrase,
      text: fit(phrase.text ?? ''),
      ...(phrase.translation === undefined ? {} : { translation: fit(phrase.translation) }),
    }));
  };
  if (word.expressions !== undefined) next.expressions = phrases(word.expressions);
  if (word.relatedWords !== undefined) next.relatedWords = phrases(word.relatedWords);
  if (word.collocations !== undefined) {
    overflow.push(...word.collocations.slice(MAX_LIST_ITEMS));
    next.collocations = word.collocations.slice(0, MAX_LIST_ITEMS).map(fit);
  }
  if (word.relatedWordIds !== undefined)
    next.relatedWordIds = word.relatedWordIds.filter((id) => id !== word.id).slice(0, MAX_LIST_ITEMS);

  for (const name of ['pos', 'pronunciation'] as const) {
    const value = word[name];
    if (value !== undefined && length(value) > MAX_SHORT_TEXT_LEN) {
      overflow.push(value);
      next[name] = clip(value, MAX_SHORT_TEXT_LEN);
    }
  }
  if (word.level !== undefined) {
    const level = word.level.trim().toUpperCase();
    if (level === '') delete next.level;
    else if (LEVELS.has(level)) next.level = level;
    else {
      // Not a CEFR band the server knows: kept in the note, never lost.
      overflow.push(word.level.trim());
      delete next.level;
    }
  }
  if (word.source !== undefined && word.source !== '' && !SOURCES.has(word.source)) next.source = 'import';
  if (word.category !== undefined && length(word.category.trim()) > MAX_CATEGORY_LEN) {
    overflow.push(word.category.trim());
    next.category = DEFAULT_CATEGORY;
  }
  for (const name of ['spellingNote', 'originalMeaning', 'correction', 'relatedNote'] as const) {
    const value = word[name];
    if (value !== undefined) next[name] = fit(value);
  }

  // The usage note takes the overflow, whole lines, as far as it can.
  const lines = [word.usageNote ?? '', ...overflow.map((line) => line.trim())].filter((line) => line !== '');
  let note = '';
  for (const line of lines) {
    const joined = note === '' ? line : `${note}; ${line}`;
    if (length(joined) <= MAX_NOTE_LEN) note = joined;
    else if (note === '') note = fit(line);
    else cut += 1;
  }
  if (note !== '') next.usageNote = note;
  else if (word.usageNote !== undefined) next.usageNote = word.usageNote;
  return { word: next, cut };
}
